    // Name -> id, -1 if unknown. "rainbow" was id 0's name before the WLED
    // palettes, and older apps still send it.
    inline int find(std::string_view name) {
        if (name == "rainbow") {
            return 0;
        }
        for (int i = 0; i < kCount; i++) {
            if (name == kNames[i]) {
                return i;
            }
        }
        return -1;
    }
